CREATE OR REPLACE FUNCTION public.membership_benefits(_user uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
 SELECT coalesce((SELECT jsonb_build_object('name',p.name,'badge',p.profile_badge,'priority_support',p.priority_support,'featured',CASE p.featured_interval WHEN 'always' THEN true WHEN 'weekly' THEN mod(floor(extract(epoch FROM (now()-s.starts_at))/86400)::integer,7)=0 WHEN 'monthly' THEN EXISTS(SELECT 1 FROM generate_series(0,1200) AS m(month_index) WHERE s.starts_at+make_interval(months=>m.month_index)<=now() AND now()<s.starts_at+make_interval(months=>m.month_index)+interval '24 hours') ELSE false END,'featured_interval',p.featured_interval,'max_active_auctions',p.max_active_auctions,'referral_pct',p.referral_pct,'starts_at',s.starts_at,'ends_at',s.ends_at) FROM public.subscriptions s JOIN public.plans p ON p.id=s.plan_id WHERE s.user_id=_user AND s.status='active' AND s.starts_at<=now() AND s.ends_at>now() AND p.audience='seller' ORDER BY s.ends_at DESC LIMIT 1),'{}'::jsonb)
$$;
CREATE OR REPLACE FUNCTION public.public_user_profile(_user uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
 SELECT jsonb_build_object('id',p.id,'display_name',p.display_name,'country',p.country,'city',p.city,'bio',p.bio,'created_at',p.created_at,'membership',jsonb_build_object('badge',public.membership_benefits(p.id)->'badge'),'rating',(SELECT avg(r.rating) FROM public.reviews r WHERE r.reviewee_id=p.id),'review_count',(SELECT count(*) FROM public.reviews r WHERE r.reviewee_id=p.id),'reviews',coalesce((SELECT jsonb_agg(v) FROM (SELECT r.rating,r.comment,r.created_at FROM public.reviews r WHERE r.reviewee_id=p.id ORDER BY r.created_at DESC LIMIT 20) v),'[]'::jsonb)) FROM public.profiles p WHERE p.id=_user AND p.account_status='active'
$$;